scwin.checkTooltipSize = function() {
	const tooltipElement = (document.getElementById('mapchart1_tooltip') || document.getElementById('mf_mapchart1_tooltip'));
	if (!tooltipElement) {
		return false;
	}
	const rect = tooltipElement.getBoundingClientRect();
	return rect.top <= 425;
};
